#include "sequencer/mdd/codec.hpp"
#include <cassert>
#include <iostream>
int main(){snake::Controller timing;timing.setSpeed(timing.core.lanes[0],5);timing.core.lanes[1].values.fill(65535);assert(timing.core.lanes[0].ticks==3&&timing.core.lanes[0].tickDenominator==2);assert(timing.core.advance(0).trigger&&timing.core.advance(0).duration==2);assert(!timing.core.advance(1).trigger);assert(timing.core.advance(2).trigger&&timing.core.advance(2).duration==1);assert(timing.core.advance(3).trigger);snake::Controller a,b;a.choose(5);a.custom=2;a.core.lanes[5].muted=123;a.core.lanes[5].ticks=3;a.core.lanes[5].tickDenominator=2;a.core.lanes[5].held=567;a.routes[2][0]={42,-123};auto text=snake::Codec::encode(a,true,123456);bool enabled=false;uint64_t tick=0;assert(snake::Codec::decode(text.data(),b,enabled,tick,64));assert(enabled&&tick==123456&&b.lane==5&&b.custom==2&&b.core.lanes[5].muted==123&&b.core.lanes[5].held==567&&b.core.lanes[5].tickDenominator==2&&b.routes[2][0].depth==-123);assert(b.gestures.lane==&b.core.lanes[5]);auto saved=b.core.lanes[5].values;assert(!snake::Codec::decode("z",b,enabled,tick,64));text[0]='2';text[1]='0';assert(!snake::Codec::decode(text.data(),b,enabled,tick,64));assert(saved==b.core.lanes[5].values);std::cout<<"PASS clip codec: atomic validation, settings, routes, mute, held and play position\n";}
